import Mathlib.Data.Real.Basic
import Mathlib.Data.Real.Sqrt
import Mathlib.Analysis.SpecialFunctions.Sqrt

noncomputable section

structure OFTB where
  dim : Nat
  dim_pos : 0 < dim
  dim_bounded : dim ≤ Nat.max / 2

def OFTB.FRACTAL_SCALE : ℝ := Real.sqrt 2 / 2

def OFTB.init (d : Nat) (hd : 0 < d) (hb : d ≤ Nat.max / 2) : OFTB :=
  { dim := d, dim_pos := hd, dim_bounded := hb }

structure Tensor where
  data : Array ℝ

inductive OFTBError where
  | InvalidDimension
  | DimensionOverflow
  | DimensionMismatch

theorem half_lt_total (d i : Nat) (hi : i < d) : i < d * 2 :=
  Nat.lt_of_lt_of_le hi (Nat.le_mul_of_pos_right d Nat.zero_lt_two)

theorem half_add_lt_total (d i : Nat) (hi : i < d) : d + i < d * 2 :=
  Nat.lt_of_lt_of_eq (Nat.add_lt_add_left hi d) (Eq.symm (Nat.mul_two d))

theorem two_nonneg_real : (0 : ℝ) ≤ 2 :=
  le_of_lt two_pos

theorem sqrt2_mul_self : Real.sqrt 2 * Real.sqrt 2 = 2 :=
  Real.mul_self_sqrt two_nonneg_real

theorem scale_sq : OFTB.FRACTAL_SCALE * OFTB.FRACTAL_SCALE = 1 / 2 :=
  calc OFTB.FRACTAL_SCALE * OFTB.FRACTAL_SCALE
      = (Real.sqrt 2 / 2) * (Real.sqrt 2 / 2) := rfl
    _ = (Real.sqrt 2 * Real.sqrt 2) / (2 * 2) := div_mul_div_comm (Real.sqrt 2) 2 (Real.sqrt 2) 2
    _ = 2 / (2 * 2) := congrArg (fun t => t / (2 * 2)) sqrt2_mul_self
    _ = 2 / (2 * 2) := rfl
    _ = 1 / 2 :=
        Eq.symm (one_div_mul_cancel two_ne_zero) ▸
          (show 2 / (2 * 2) = 1 / 2 from
            Eq.trans
              (show (2 : ℝ) / (2 * 2) = 2 * (2 * 2)⁻¹ from div_eq_mul_inv 2 (2 * 2))
              (Eq.trans
                (congrArg (fun t => 2 * t) (show (2 * 2 : ℝ)⁻¹ = 2⁻¹ * 2⁻¹ from mul_inv_rev 2 2))
                (Eq.trans
                  (mul_assoc 2 2⁻¹ 2⁻¹)
                  (Eq.trans
                    (congrArg (fun t => t * 2⁻¹) (mul_inv_cancel₀ two_ne_zero))
                    (one_mul 2⁻¹)))))

theorem half_mul_two_eq_one : (1 / 2 : ℝ) * 2 = 1 :=
  calc (1 / 2 : ℝ) * 2
      = (1 * 2) / 2 := Eq.symm (div_mul_eq_mul_div 1 2 2)
    _ = 2 / 2 := congrArg (fun t => t / 2) (one_mul 2)
    _ = 1 := div_self two_ne_zero

theorem scale_mul_scale_mul_two (a : ℝ) : OFTB.FRACTAL_SCALE * OFTB.FRACTAL_SCALE * (2 * a) = a :=
  calc OFTB.FRACTAL_SCALE * OFTB.FRACTAL_SCALE * (2 * a)
      = (1 / 2 : ℝ) * (2 * a) := congrArg (fun t => t * (2 * a)) scale_sq
    _ = (1 / 2 : ℝ) * 2 * a := Eq.symm (mul_assoc (1 / 2) 2 a)
    _ = 1 * a := congrArg (fun t => t * a) half_mul_two_eq_one
    _ = a := one_mul a

theorem helper_add_pair' (a b : ℝ) : (a - b) + (a + b) = 2 * a :=
  calc (a - b) + (a + b)
      = a + -b + (a + b) := congrArg (fun t => t + (a + b)) (sub_eq_add_neg a b)
    _ = a + (-b + (a + b)) := add_assoc a (-b) (a + b)
    _ = a + (-b + a + b) := congrArg (HAdd.hAdd a) (Eq.symm (add_assoc (-b) a b))
    _ = a + (a + -b + b) := congrArg (HAdd.hAdd a) (congrArg (fun t => t + b) (add_comm (-b) a))
    _ = a + (a + (-b + b)) := congrArg (HAdd.hAdd a) (add_assoc a (-b) b)
    _ = a + (a + 0) := congrArg (HAdd.hAdd a) (congrArg (HAdd.hAdd a) (neg_add_cancel b))
    _ = a + a := congrArg (HAdd.hAdd a) (add_zero a)
    _ = 2 * a := Eq.symm (two_mul a)

theorem helper_sub_pair' (a b : ℝ) : (a + b) - (a - b) = 2 * b :=
  calc (a + b) - (a - b)
      = (a + b) + -(a - b) := sub_eq_add_neg (a + b) (a - b)
    _ = (a + b) + -(a + -b) := congrArg (fun t => (a + b) + t) (congrArg Neg.neg (sub_eq_add_neg a b))
    _ = (a + b) + (-a + -(-b)) := congrArg (fun t => (a + b) + t) (neg_add a (-b))
    _ = (a + b) + (-a + b) := congrArg (fun t => (a + b) + t) (congrArg (HAdd.hAdd (-a)) (neg_neg b))
    _ = a + (b + (-a + b)) := add_assoc a b (-a + b)
    _ = a + (b + -a + b) := congrArg (HAdd.hAdd a) (Eq.symm (add_assoc b (-a) b))
    _ = a + (-a + b + b) := congrArg (HAdd.hAdd a) (congrArg (fun t => t + b) (add_comm b (-a)))
    _ = a + (-a + (b + b)) := congrArg (HAdd.hAdd a) (add_assoc (-a) b b)
    _ = a + -a + (b + b) := Eq.symm (add_assoc a (-a) (b + b))
    _ = 0 + (b + b) := congrArg (fun t => t + (b + b)) (add_neg_cancel a)
    _ = b + b := zero_add (b + b)
    _ = 2 * b := Eq.symm (two_mul b)

def forwardScalar (a b : ℝ) : ℝ × ℝ :=
  let s := OFTB.FRACTAL_SCALE
  (s * (a - b), s * (a + b))

def backwardScalar (a b : ℝ) : ℝ × ℝ :=
  let s := OFTB.FRACTAL_SCALE
  (s * (a + b), s * (b - a))

theorem forward_backward_scalar (a b : ℝ) :
    backwardScalar (forwardScalar a b).1 (forwardScalar a b).2 = (a, b) :=
  let s := OFTB.FRACTAL_SCALE
  let a' := s * (a - b)
  let b' := s * (a + b)
  have hsum : a' + b' = s * (2 * a) :=
    Eq.trans (Eq.symm (mul_add s (a - b) (a + b)))
      (congrArg (HMul.hMul s) (helper_add_pair' a b))
  have hdif : b' - a' = s * (2 * b) :=
    Eq.trans (Eq.symm (mul_sub s (a + b) (a - b)))
      (congrArg (HMul.hMul s) (helper_sub_pair' a b))
  have ha : s * (a' + b') = a :=
    Eq.trans (congrArg (HMul.hMul s) hsum)
      (Eq.trans (Eq.symm (mul_assoc s s (2 * a))) (scale_mul_scale_mul_two a))
  have hb : s * (b' - a') = b :=
    Eq.trans (congrArg (HMul.hMul s) hdif)
      (Eq.trans (Eq.symm (mul_assoc s s (2 * b))) (scale_mul_scale_mul_two b))
  Prod.ext ha hb

theorem forward_backward_point (a b : ℝ) :
    (let s := OFTB.FRACTAL_SCALE
     let a' := (a - b) * s
     let b' := (a + b) * s
     ((a' + b') * s, (b' - a') * s)) = (a, b) :=
  let s := OFTB.FRACTAL_SCALE
  have hc1 : (a - b) * s = s * (a - b) := mul_comm (a - b) s
  have hc2 : (a + b) * s = s * (a + b) := mul_comm (a + b) s
  have h := forward_backward_scalar a b
  have h1 : s * (s * (a - b) + s * (a + b)) = a := congrArg Prod.fst h
  have h2 : s * (s * (a + b) - s * (a - b)) = b := congrArg Prod.snd h
  have k1 : ((a - b) * s + (a + b) * s) * s =
      (s * (a - b) + s * (a + b)) * s :=
    congrArg (fun t => t * s)
      (congrArg₂ HAdd.hAdd hc1 hc2)
  have k1' : (s * (a - b) + s * (a + b)) * s = s * (s * (a - b) + s * (a + b)) :=
    mul_comm _ s
  have k2 : ((a + b) * s - (a - b) * s) * s =
      (s * (a + b) - s * (a - b)) * s :=
    congrArg (fun t => t * s)
      (congrArg₂ HSub.hSub hc2 hc1)
  have k2' : (s * (a + b) - s * (a - b)) * s = s * (s * (a + b) - s * (a - b)) :=
    mul_comm _ s
  Prod.ext
    (Eq.trans k1 (Eq.trans k1' h1))
    (Eq.trans k2 (Eq.trans k2' h2))

partial def forwardInPlaceCore (half : Nat) (data : Array ℝ) (i : Nat) : Array ℝ :=
  if h1 : i < half then
    if h2 : half + i < data.size then
      if h3 : i < data.size then
        let a := data.get ⟨i, h3⟩
        let b := data.get ⟨half + i, h2⟩
        let s := OFTB.FRACTAL_SCALE
        let data1 := data.set ⟨i, h3⟩ (s * (a - b))
        let hs1 : data1.size = data.size := Array.size_set data ⟨i, h3⟩ (s * (a - b))
        let h3' : i < data1.size := hs1.symm ▸ h3
        let h2' : half + i < data1.size := hs1.symm ▸ h2
        let data2 := data1.set ⟨half + i, h2'⟩ (s * (a + b))
        forwardInPlaceCore half data2 (i + 1)
      else data
    else data
  else data

partial def backwardInPlaceCore (half : Nat) (data : Array ℝ) (i : Nat) : Array ℝ :=
  if h1 : i < half then
    if h2 : half + i < data.size then
      if h3 : i < data.size then
        let a := data.get ⟨i, h3⟩
        let b := data.get ⟨half + i, h2⟩
        let s := OFTB.FRACTAL_SCALE
        let data1 := data.set ⟨i, h3⟩ (s * (a + b))
        let hs1 : data1.size = data.size := Array.size_set data ⟨i, h3⟩ (s * (a + b))
        let h3' : i < data1.size := hs1.symm ▸ h3
        let h2' : half + i < data1.size := hs1.symm ▸ h2
        let data2 := data1.set ⟨half + i, h2'⟩ (s * (b - a))
        backwardInPlaceCore half data2 (i + 1)
      else data
    else data
  else data

partial theorem forward_preserves_length_core (half : Nat) (data : Array ℝ) (i : Nat) :
    (forwardInPlaceCore half data i).size = data.size :=
  if h : i < half then
    if h2 : half + i < data.size then
      if h1 : i < data.size then
        let a := data.get ⟨i, h1⟩
        let b := data.get ⟨half + i, h2⟩
        let s := OFTB.FRACTAL_SCALE
        let data1 := data.set ⟨i, h1⟩ (s * (a - b))
        let hs1 : data1.size = data.size := Array.size_set data ⟨i, h1⟩ (s * (a - b))
        let h1' : i < data1.size := Eq.subst (Eq.symm hs1) h1
        let h2' : half + i < data1.size := Eq.subst (Eq.symm hs1) h2
        let data2 := data1.set ⟨half + i, h2'⟩ (s * (a + b))
        let hs2 : data2.size = data1.size := Array.size_set data1 ⟨half + i, h2'⟩ (s * (a + b))
        Eq.trans (forward_preserves_length_core half data2 (i + 1)) (Eq.trans hs2 hs1)
      else Eq.refl (data.size)
    else Eq.refl (data.size)
  else Eq.refl (data.size)

partial theorem backward_preserves_length_core (half : Nat) (data : Array ℝ) (i : Nat) :
    (backwardInPlaceCore half data i).size = data.size :=
  if h : i < half then
    if h2 : half + i < data.size then
      if h1 : i < data.size then
        let a := data.get ⟨i, h1⟩
        let b := data.get ⟨half + i, h2⟩
        let s := OFTB.FRACTAL_SCALE
        let data1 := data.set ⟨i, h1⟩ (s * (a + b))
        let hs1 : data1.size = data.size := Array.size_set data ⟨i, h1⟩ (s * (a + b))
        let h1' : i < data1.size := Eq.subst (Eq.symm hs1) h1
        let h2' : half + i < data1.size := Eq.subst (Eq.symm hs1) h2
        let data2 := data1.set ⟨half + i, h2'⟩ (s * (b - a))
        let hs2 : data2.size = data1.size := Array.size_set data1 ⟨half + i, h2'⟩ (s * (b - a))
        Eq.trans (backward_preserves_length_core half data2 (i + 1)) (Eq.trans hs2 hs1)
      else Eq.refl (data.size)
    else Eq.refl (data.size)
  else Eq.refl (data.size)

def OFTB.forwardInPlace (self : OFTB) (x : Tensor) : Except OFTBError Tensor :=
  match Nat.decEq self.dim 0 with
  | isTrue _ => Except.error OFTBError.InvalidDimension
  | isFalse _ =>
    match Nat.decLt (Nat.max / 2) self.dim with
    | isTrue _ => Except.error OFTBError.DimensionOverflow
    | isFalse _ =>
      match decEq x.data.size (self.dim * 2) with
      | isFalse _ => Except.error OFTBError.DimensionMismatch
      | isTrue _ => Except.ok ⟨forwardInPlaceCore self.dim x.data 0⟩

theorem OFTB_forward_mismatch (d : Nat) (x : Tensor)
    (hd : 0 < d) (hmax : d ≤ Nat.max / 2)
    (hlen : x.data.size ≠ d * 2) :
    OFTB.forwardInPlace ⟨d, hd, hmax⟩ x = Except.error OFTBError.DimensionMismatch :=
  have hne0 : d ≠ 0 := Nat.ne_of_gt hd
  have hnov : ¬ (Nat.max / 2 < d) := fun h => Nat.not_le_of_gt h hmax
  match heq0 : Nat.decEq d 0 with
  | isTrue h0 => False.elim (hne0 h0)
  | isFalse _ =>
    match hlt : Nat.decLt (Nat.max / 2) d with
    | isTrue hl => False.elim (hnov hl)
    | isFalse _ =>
      match heq : decEq x.data.size (d * 2) with
      | isTrue hlen_eq => False.elim (hlen hlen_eq)
      | isFalse _ => rfl

def OFTB.backwardInPlace (self : OFTB) (x : Tensor) : Except OFTBError Tensor :=
  match Nat.decEq self.dim 0 with
  | isTrue _ => Except.error OFTBError.InvalidDimension
  | isFalse _ =>
    match Nat.decLt (Nat.max / 2) self.dim with
    | isTrue _ => Except.error OFTBError.DimensionOverflow
    | isFalse _ =>
      match decEq x.data.size (self.dim * 2) with
      | isFalse _ => Except.error OFTBError.DimensionMismatch
      | isTrue _ => Except.ok ⟨backwardInPlaceCore self.dim x.data 0⟩

def get2 (data : Array ℝ) (half i : Nat) (h1 : i < data.size) (h2 : half + i < data.size) : ℝ × ℝ :=
  (data.get ⟨i, h1⟩, data.get ⟨half + i, h2⟩)

def set2 (data : Array ℝ) (half i : Nat) (h1 : i < data.size) (h2 : half + i < data.size) (v1 v2 : ℝ) : Array ℝ :=
  let data1 := data.set ⟨i, h1⟩ v1
  let h2' : half + i < data1.size := Eq.subst (Eq.symm (Array.size_set data ⟨i, h1⟩ v1)) h2
  data1.set ⟨half + i, h2'⟩ v2

theorem size_set2 (data : Array ℝ) (half i : Nat) (h1 : i < data.size) (h2 : half + i < data.size) (v1 v2 : ℝ) :
    (set2 data half i h1 h2 v1 v2).size = data.size :=
  let data1 := data.set ⟨i, h1⟩ v1
  let hs1 : data1.size = data.size := Array.size_set data ⟨i, h1⟩ v1
  let h2' : half + i < data1.size := Eq.subst (Eq.symm hs1) h2
  let hs2 : (data1.set ⟨half + i, h2'⟩ v2).size = data1.size := Array.size_set data1 ⟨half + i, h2'⟩ v2
  Eq.trans hs2 hs1

theorem helper_sq_sum_diff (X Y Z : ℝ) : ((X - Y) + Z) + ((X + Y) + Z) = 2 * X + 2 * Z :=
  calc ((X - Y) + Z) + ((X + Y) + Z)
      = (X + -Y) + Z + ((X + Y) + Z) := congrArg (fun t => t + Z + ((X + Y) + Z)) (sub_eq_add_neg X Y)
    _ = (X + -Y) + (Z + ((X + Y) + Z)) := add_assoc (X + -Y) Z ((X + Y) + Z)
    _ = (X + -Y) + (((X + Y) + Z) + Z) := congrArg (HAdd.hAdd (X + -Y)) (add_comm Z ((X + Y) + Z))
    _ = (X + -Y) + ((X + Y) + (Z + Z)) := congrArg (HAdd.hAdd (X + -Y)) (add_assoc (X + Y) Z Z)
    _ = ((X + -Y) + (X + Y)) + (Z + Z) := Eq.symm (add_assoc (X + -Y) (X + Y) (Z + Z))
    _ = (X + (-Y + (X + Y))) + (Z + Z) := congrArg (fun t => t + (Z + Z)) (add_assoc X (-Y) (X + Y))
    _ = (X + ((-Y + X) + Y)) + (Z + Z) := congrArg (fun t => t + (Z + Z)) (congrArg (HAdd.hAdd X) (Eq.symm (add_assoc (-Y) X Y)))
    _ = (X + ((X + -Y) + Y)) + (Z + Z) := congrArg (fun t => t + (Z + Z)) (congrArg (HAdd.hAdd X) (congrArg (fun t => t + Y) (add_comm (-Y) X)))
    _ = (X + (X + (-Y + Y))) + (Z + Z) := congrArg (fun t => t + (Z + Z)) (congrArg (HAdd.hAdd X) (add_assoc X (-Y) Y))
    _ = (X + (X + 0)) + (Z + Z) := congrArg (fun t => t + (Z + Z)) (congrArg (HAdd.hAdd X) (congrArg (HAdd.hAdd X) (neg_add_cancel Y)))
    _ = (X + X) + (Z + Z) := congrArg (fun t => t + (Z + Z)) (congrArg (HAdd.hAdd X) (add_zero X))
    _ = 2 * X + (Z + Z) := congrArg (fun t => t + (Z + Z)) (Eq.symm (two_mul X))
    _ = 2 * X + 2 * Z := congrArg (HAdd.hAdd (2 * X)) (Eq.symm (two_mul Z))

theorem sq_sum_diff (a b : ℝ) :
    (a - b) ^ 2 + (a + b) ^ 2 = 2 * a ^ 2 + 2 * b ^ 2 :=
  Eq.trans
    (congrArg₂ HAdd.hAdd (sub_sq a b) (add_sq a b))
    (Eq.trans
      (congrArg (HAdd.hAdd (a ^ 2 - 2 * a * b + b ^ 2)) (add_sq a b))
      (helper_sq_sum_diff (a ^ 2) (2 * a * b) (b ^ 2)))

theorem mul_mul_mul_comm (a b c d : ℝ) : (a * b) * (c * d) = (a * c) * (b * d) :=
  calc (a * b) * (c * d)
      = a * (b * (c * d)) := mul_assoc a b (c * d)
    _ = a * ((b * c) * d) := congrArg (HMul.hMul a) (Eq.symm (mul_assoc b c d))
    _ = a * ((c * b) * d) := congrArg (HMul.hMul a) (congrArg (fun t => t * d) (mul_comm b c))
    _ = a * (c * (b * d)) := congrArg (HMul.hMul a) (mul_assoc c b d)
    _ = (a * c) * (b * d) := Eq.symm (mul_assoc a c (b * d))

theorem orthog_norm_scalar (a b : ℝ) :
    let s := OFTB.FRACTAL_SCALE
    (s * (a - b)) * (s * (a - b)) + (s * (a + b)) * (s * (a + b)) = a * a + b * b :=
  let s := OFTB.FRACTAL_SCALE
  have hss : s * s = 1 / 2 := scale_sq
  have h1 : (s * (a - b)) * (s * (a - b)) = (s * s) * ((a - b) ^ 2) :=
    Eq.trans (mul_mul_mul_comm s (a - b) s (a - b))
      (congrArg (HMul.hMul (s * s)) (Eq.symm (pow_two (a - b))))
  have h2 : (s * (a + b)) * (s * (a + b)) = (s * s) * ((a + b) ^ 2) :=
    Eq.trans (mul_mul_mul_comm s (a + b) s (a + b))
      (congrArg (HMul.hMul (s * s)) (Eq.symm (pow_two (a + b))))
  have step1 : (s * (a - b)) * (s * (a - b)) + (s * (a + b)) * (s * (a + b)) = (s * s) * ((a - b) ^ 2) + (s * s) * ((a + b) ^ 2) :=
    congrArg₂ HAdd.hAdd h1 h2
  have step2 : (s * s) * ((a - b) ^ 2) + (s * s) * ((a + b) ^ 2) = (s * s) * ((a - b) ^ 2 + (a + b) ^ 2) :=
    Eq.symm (mul_add (s * s) ((a - b) ^ 2) ((a + b) ^ 2))
  have step3 : (s * s) * ((a - b) ^ 2 + (a + b) ^ 2) = (s * s) * (2 * a ^ 2 + 2 * b ^ 2) :=
    congrArg (HMul.hMul (s * s)) (sq_sum_diff a b)
  have step4 : (s * s) * (2 * a ^ 2 + 2 * b ^ 2) = (1 / 2 : ℝ) * (2 * a ^ 2 + 2 * b ^ 2) :=
    congrArg (fun t => t * (2 * a ^ 2 + 2 * b ^ 2)) hss
  have step5 : (1 / 2 : ℝ) * (2 * a ^ 2 + 2 * b ^ 2) = (1 / 2 : ℝ) * (2 * (a ^ 2 + b ^ 2)) :=
    congrArg (HMul.hMul (1 / 2 : ℝ)) (Eq.symm (mul_add 2 (a ^ 2) (b ^ 2)))
  have step6 : (1 / 2 : ℝ) * (2 * (a ^ 2 + b ^ 2)) = ((1 / 2 : ℝ) * 2) * (a ^ 2 + b ^ 2) :=
    Eq.symm (mul_assoc (1 / 2 : ℝ) 2 (a ^ 2 + b ^ 2))
  have step7 : ((1 / 2 : ℝ) * 2) * (a ^ 2 + b ^ 2) = 1 * (a ^ 2 + b ^ 2) :=
    congrArg (fun t => t * (a ^ 2 + b ^ 2)) half_mul_two_eq_one
  have step8 : 1 * (a ^ 2 + b ^ 2) = a ^ 2 + b ^ 2 := one_mul (a ^ 2 + b ^ 2)
  have step9 : a ^ 2 + b ^ 2 = a * a + b * b :=
    congrArg₂ HAdd.hAdd (pow_two a) (pow_two b)
  Eq.trans step1 (Eq.trans step2 (Eq.trans step3 (Eq.trans step4 (Eq.trans step5 (Eq.trans step6 (Eq.trans step7 (Eq.trans step8 step9)))))))

end const std = @import("std");
const Tensor = @import("../core/tensor.zig").Tensor;

pub const OFTB = struct {
    pub const FRACTAL_SCALE: f32 = 0.7071067811865476;

    dim: usize,

    pub fn init(d: usize) OFTB {
        std.debug.assert(d != 0);
        std.debug.assert(d <= std.math.maxInt(usize) / 2);
        return OFTB{
            .dim = d,
        };
    }

    pub fn deinit(self: *OFTB) void {
        self.* = undefined;
    }

    pub fn forwardInPlace(self: OFTB, x: *Tensor) !void {
        if (self.dim == 0) return error.InvalidDimension;
        if (self.dim > std.math.maxInt(usize) / 2) return error.DimensionOverflow;
        const total = self.dim * 2;
        if (x.data.len != total) return error.DimensionMismatch;
        const half = self.dim;
        const x1 = x.data[0..half];
        const x2 = x.data[half..][0..half];
        const scale: f32 = FRACTAL_SCALE;
        const VLEN: usize = 8;
        var i: usize = 0;
        while (i + VLEN <= half) : (i += VLEN) {
            const va: @Vector(VLEN, f32) = x1[i..][0..VLEN].*;
            const vb: @Vector(VLEN, f32) = x2[i..][0..VLEN].*;
            const vscale: @Vector(VLEN, f32) = @splat(scale);
            x1[i..][0..VLEN].* = (va - vb) * vscale;
            x2[i..][0..VLEN].* = (va + vb) * vscale;
        }
        while (i < half) : (i += 1) {
            const a = x1[i];
            const b = x2[i];
            x1[i] = (a - b) * scale;
            x2[i] = (a + b) * scale;
        }
    }

    pub fn backwardInPlace(self: OFTB, grad: []f32) !void {
        if (self.dim == 0) return error.InvalidDimension;
        if (self.dim > std.math.maxInt(usize) / 2) return error.DimensionOverflow;
        const total = self.dim * 2;
        if (grad.len != total) return error.DimensionMismatch;
        const half = self.dim;
        const g1 = grad[0..half];
        const g2 = grad[half..][0..half];
        const scale: f32 = FRACTAL_SCALE;
        const VLEN: usize = 8;
        var i: usize = 0;
        while (i + VLEN <= half) : (i += VLEN) {
            const va: @Vector(VLEN, f32) = g1[i..][0..VLEN].*;
            const vb: @Vector(VLEN, f32) = g2[i..][0..VLEN].*;
            const vscale: @Vector(VLEN, f32) = @splat(scale);
            g1[i..][0..VLEN].* = (va + vb) * vscale;
            g2[i..][0..VLEN].* = (vb - va) * vscale;
        }
        while (i < half) : (i += 1) {
            const a = g1[i];
            const b = g2[i];
            g1[i] = (a + b) * scale;
            g2[i] = (b - a) * scale;
        }
    }
};

pub fn mixForward(oftb: OFTB, x: *Tensor) !void {
    try oftb.forwardInPlace(x);
}

pub fn mixBackward(oftb: OFTB, grad: []f32) !void {
    try oftb.backwardInPlace(grad);
}

comptime {
    _ = OFTB;
}

test "OFTB forward then backward returns input within 1e-5 tolerance" {
    const allocator = std.testing.allocator;
    var prng = std.Random.DefaultPrng.init(42);
    const random = prng.random();

    const dim: usize = 32;
    const total = dim * 2;

    var input = try Tensor.init(allocator, &.{ 1, total });
    defer input.deinit();
    var i: usize = 0;
    while (i < input.data.len) : (i += 1) {
        input.data[i] = (random.float(f32) - 0.5) * 2.0;
    }

    const original = try allocator.dupe(f32, input.data);
    defer allocator.free(original);

    var oftb = OFTB.init(dim);
    try oftb.forwardInPlace(&input);
    try oftb.backwardInPlace(input.data);

    i = 0;
    while (i < input.data.len) : (i += 1) {
        try std.testing.expectApproxEqAbs(input.data[i], original[i], 1e-5);
    }
}
